sys_script_include.script:
var OnboardingAjax = Class.create();
OnboardingAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    // Returns the manager's department sys_id (or '' if none)
    getDepartment: function () {
        var user = new GlideRecord('sys_user');
        if (!user.get(this.getParameter('sysparm_user'))) return '';
        return user.getValue('department') || '';
    },

    // Returns 'true' if the date (in the user's format) is before today
    isPastDate: function () {
        var picked = new GlideDate();
        picked.setDisplayValue(this.getParameter('sysparm_date'));
        return String(picked.getValue() < new GlideDate().getValue());
    },

    type: 'OnboardingAjax'
});
